#ifndef CSM_TRANSCRIPT_H
#define CSM_TRANSCRIPT_H

#include <stddef.h>
#include <time.h>

/* What one entry of a conversation is. */
enum transcript_kind {
	TRANSCRIPT_USER,	/* a prompt */
	TRANSCRIPT_IMAGE,	/* an image the user gave */
	TRANSCRIPT_DOCUMENT,	/* a document the user gave */
	TRANSCRIPT_CLAUDE,	/* text of a reply */
	TRANSCRIPT_TOOL,	/* a tool call */
	TRANSCRIPT_RESULT,	/* what the tool gave back */
	TRANSCRIPT_COMPACT	/* the conversation was compacted here */
};

struct transcript_entry {
	enum transcript_kind kind;
	time_t when;		/* the line's timestamp; 0 when unknown */
	char *text;		/* USER, CLAUDE: the text; TOOL: the name */
	char *arg;		/* TOOL: its main argument; NULL when none */
	size_t lines;		/* RESULT: lines of the result */
	int error;		/* RESULT: the tool failed */
};

/* A conversation as the session view shows it, in file order. */
struct transcript {
	struct transcript_entry *entries;
	size_t count, cap;
};

/* What a line of the view is, for its look. */
enum view_style {
	VIEW_BLANK,
	VIEW_HEAD_USER,		/* "You · time" over the user's entries */
	VIEW_HEAD_CLAUDE,	/* "Claude · time" over a reply */
	VIEW_TEXT,		/* a prompt or a reply */
	VIEW_TOOL,		/* a tool call or its result */
	VIEW_NOTE		/* compacted here, or nothing to show */
};

struct view_line {
	enum view_style style;
	char *text;
};

int transcript_read(const char *file, struct transcript *tr);
void transcript_free(struct transcript *tr);
struct view_line *transcript_lines(const struct transcript *tr, size_t width,
    size_t *count);
void transcript_lines_free(struct view_line *lines, size_t count);

#endif
